#!/bin/busybox sh
# PID 1 of every board's initramfs: sets up just enough of a system for the
# app, then runs it, restarting it if it exits. Board specifics come from
# /etc/ec.env (generated by ./ec from boards/<name>/board.sh) and, when the
# board has one, the /etc/board-init.sh hook.
/bin/busybox mkdir -p /sbin /usr/bin /usr/sbin
/bin/busybox --install -s
mount -t proc proc /proc
mount -t sysfs sysfs /sys
mount -t tmpfs tmpfs /tmp
dmesg -n 1   # keep kernel messages (and the app's kmsg copies) off the console
. /etc/ec.env

# /dev: devtmpfs when the kernel has it, else nodes made from sysfs (older
# Android kernels rely on ueventd and have no devtmpfs).
if ! mount -t devtmpfs devtmpfs /dev 2>/dev/null; then
  mknod -m 666 /dev/null c 1 3
  mknod -m 600 /dev/kmsg c 1 11
fi
mkdir -p /dev/input /dev/graphics

# Framebuffers where minui looks for them (/dev/graphics/fbN, Android's
# naming) and input devices, for whatever has probed so far.
mknodes() {
  for d in /sys/class/graphics/fb* /sys/class/input/event*; do
    [ -f "$d/dev" ] || continue
    n=${d##*/}
    case $d in
      */graphics/*)
        [ -e "/dev/$n" ] && ln -sf "/dev/$n" "/dev/graphics/$n" 2>/dev/null
        [ -e "/dev/graphics/$n" ] || mknod "/dev/graphics/$n" c $(tr ':' ' ' < "$d/dev") ;;
      *) [ -e "/dev/input/$n" ] || mknod "/dev/input/$n" c $(tr ':' ' ' < "$d/dev") ;;
    esac
  done
}

# Wait (up to EC_WAIT_SECS) for the display and, if the board names one, the
# input device whose name matches EC_WAIT_INPUT.
i=0
while [ $i -lt $((${EC_WAIT_SECS:-10} * 2)) ]; do
  mknodes
  if [ -e /dev/graphics/fb0 ] || [ -e /dev/dri/card0 ]; then
    [ -z "$EC_WAIT_INPUT" ] && break
    grep -qil "$EC_WAIT_INPUT" /sys/class/input/input*/name 2>/dev/null && break
  fi
  sleep 0.5
  i=$((i + 1))
done
mknodes

[ -f /etc/board-init.sh ] && . /etc/board-init.sh

# ec.trace=1 on the kernel command line (QEMU: TRACE=1) overrides ec.env.
t=$(sed -n 's/.*ec\.trace=\([01]\).*/\1/p' /proc/cmdline)
[ -n "$t" ] && export EC_TRACE=$t
say() { if [ "$EC_LOG" = kmsg ]; then echo "$*" > /dev/kmsg; else echo "$*"; fi; }
say "=== embedded-compose on $(uname -r), input: $(ls /dev/input | tr '\n' ' ')"
n=0
while true; do
  n=$((n + 1))
  say "=== start #$n"
  if [ "$EC_LOG" = kmsg ]; then
    /bin/embedded-compose > /dev/kmsg 2>/dev/null   # the app logs to kmsg itself
  else
    /bin/embedded-compose
  fi
  say "=== embedded-compose exited: $?"
  sleep 1
done
